import json

def parse_large_json(file_path):
    with open(file_path, 'r', encoding='utf-8') as f:
        for line in f:
            line = line.strip()
            if line and line not in ('[', ']'):
                if line.endswith(','):
                    line = line[:-1]
                yield json.loads(line)

